#pragma once

#include "ocudu/adt/span.h"
#include "ocudu/dapp/e3/e3ap_protocol.h"
#include "ocudu/dapp/e3/result.h"

namespace ocudu::dapp::e3 {

/// APER codec for E3AP-OCUDU-V2 (schemas/e3/e3ap-ocudu-v2.asn1): the upstream libe3 E3AP 1.0.0 module
/// with OCUDU extension additions, generated by the pinned asn1c.
///
/// Because V2's root is libe3's module, one codec serves both kinds of peer:
///  - \ref e3ap_profile::libe3: no addition is written or read, so the bytes are libe3's own
///    (checked against vectors from libe3's Asn1E3Encoder). Values the libe3 module cannot carry fail
///    to encode with a diagnostic: E3-ControlResponse, fragmented or by-reference payloads, payloads
///    above 32 KiB, a report or xApp control without a sequence identifier. OCUDU-only optional
///    fields (causes, detail, subscription data, ...) are dropped.
///  - \ref e3ap_profile::ocudu: the additions are carried. A libe3 decoder still reads such a PDU as
///    the libe3 message (APER extension additions are skippable open types).
class e3ap_v2_codec
{
public:
  /// Identifier bounds (E3-DAppID and every other 1..65535 identifier).
  static constexpr uint32_t maximum_identifier = 65535;
  /// E3-MessageID and E3-SequenceID: 1..4294967295.
  static constexpr uint32_t    maximum_message_id   = 4294967295U;
  static constexpr std::size_t maximum_list_entries = 1000;
  static constexpr std::size_t maximum_payload_bytes = 32768;
  static constexpr std::size_t maximum_name_bytes    = 64;
  static constexpr std::size_t maximum_version_bytes = 11;
  static constexpr std::size_t maximum_text_bytes    = 512;
  /// Largest single E3-PDU accepted on the wire.
  static constexpr std::size_t maximum_pdu_bytes = 64 * 1024;

  static codec_result<std::vector<uint8_t>> encode(const e3ap_pdu& pdu, e3ap_profile profile) noexcept;
  static codec_result<e3ap_pdu>             decode(ocudu::span<const uint8_t> bytes, e3ap_profile profile) noexcept;

  /// True when \p message can be expressed under \p profile as-is.
  static bool representable(const e3ap_message& message, e3ap_profile profile, std::string* detail = nullptr) noexcept;
};

} // namespace ocudu::dapp::e3
